package com.campusconnect.controller;
import com.campusconnect.service.*; import javafx.application.Platform; import javafx.fxml.FXML; import javafx.scene.control.*;
public class AdminDashboardController { @FXML private Label students,pending,resolved,lost,found,events,registrations; @FXML private Button navButton;
 @FXML private void initialize(){new Thread(()->{try{StudentService s=new StudentService();ComplaintService c=new ComplaintService();LostFoundService l=new LostFoundService();EventService e=new EventService();var all=e.all();Platform.runLater(()->{students.setText(""+s.count());pending.setText(""+c.pending());resolved.setText(""+c.resolved());lost.setText(""+l.lost());found.setText(""+l.found());events.setText(""+all.stream().filter(x->x.getDate()!=null&&x.getDate().isAfter(java.time.LocalDate.now().minusDays(1))).count());registrations.setText(""+e.totalRegistrations());});}catch(Exception ex){Platform.runLater(()->UiUtil.error("Could not load dashboard statistics."));}}).start();}
 @FXML private void students(){UiUtil.scene(navButton,"students.fxml");} @FXML private void complaints(){UiUtil.scene(navButton,"complaints.fxml");} @FXML private void lostFound(){UiUtil.scene(navButton,"lost-found.fxml");} @FXML private void events(){UiUtil.scene(navButton,"events.fxml");} @FXML private void logout(){com.campusconnect.util.SessionManager.logout();UiUtil.scene(navButton,"login.fxml");} }
